import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Initialize fonts at module level to prevent render flicker
const { fontFamily: interFamily } = loadInter();

// Schema Definitions


export type LocalPopulationMapProps = Record<string, any>;

// Pre-computed organic crowd layout (x, y offsets relative to center, s = scale, c = color layer)
const CROWD_CONFIG = [
  // Layer 0 (Back)
  { x: -280, y: -60, s: 0.6, c: 0 }, { x: -240, y: -70, s: 0.6, c: 0 }, { x: -200, y: -80, s: 0.6, c: 0 }, { x: -160, y: -85, s: 0.6, c: 0 }, { x: -120, y: -90, s: 0.6, c: 0 }, { x: -80, y: -95, s: 0.6, c: 0 }, { x: -40, y: -95, s: 0.6, c: 0 }, { x: 0, y: -95, s: 0.6, c: 0 }, { x: 40, y: -95, s: 0.6, c: 0 }, { x: 80, y: -95, s: 0.6, c: 0 }, { x: 120, y: -90, s: 0.6, c: 0 }, { x: 160, y: -85, s: 0.6, c: 0 }, { x: 200, y: -80, s: 0.6, c: 0 }, { x: 240, y: -70, s: 0.6, c: 0 }, { x: 280, y: -60, s: 0.6, c: 0 },
  // Layer 1
  { x: -250, y: -20, s: 0.7, c: 1 }, { x: -190, y: -30, s: 0.7, c: 1 }, { x: -130, y: -40, s: 0.7, c: 1 }, { x: -80, y: -45, s: 0.7, c: 1 }, { x: -30, y: -50, s: 0.7, c: 1 }, { x: 20, y: -50, s: 0.7, c: 1 }, { x: 70, y: -45, s: 0.7, c: 1 }, { x: 120, y: -40, s: 0.7, c: 1 }, { x: 170, y: -30, s: 0.7, c: 1 }, { x: 230, y: -20, s: 0.7, c: 1 },
  // Layer 2
  { x: -180, y: 30, s: 0.85, c: 2 }, { x: -120, y: 20, s: 0.85, c: 2 }, { x: -60, y: 10, s: 0.85, c: 2 }, { x: 0, y: 5, s: 0.85, c: 2 }, { x: 60, y: 10, s: 0.85, c: 2 }, { x: 120, y: 20, s: 0.85, c: 2 }, { x: 180, y: 30, s: 0.85, c: 2 },
  // Layer 3
  { x: -110, y: 90, s: 1.05, c: 3 }, { x: -40, y: 80, s: 1.05, c: 3 }, { x: 40, y: 80, s: 1.05, c: 3 }, { x: 110, y: 90, s: 1.05, c: 3 },
  // Layer 4 (Front)
  { x: -50, y: 150, s: 1.25, c: 4 }, { x: 50, y: 150, s: 1.25, c: 4 }
];

// Reusable SVG Icons
const PersonIcon = ({ color, style, className }: { color: string; style?: React.CSSProperties; className?: string }) => (
  <svg viewBox="0 0 100 200" style={{ ...style, overflow: "visible" }} className={className}>
    <circle cx="50" cy="30" r="22" fill={color} />
    <rect x="20" y="58" width="60" height="70" rx="15" fill={color} />
    <rect x="5" y="65" width="18" height="65" rx="9" fill={color} />
    <rect x="77" y="65" width="18" height="65" rx="9" fill={color} />
    <rect x="25" y="120" width="20" height="70" rx="10" fill={color} />
    <rect x="55" y="120" width="20" height="70" rx="10" fill={color} />
  </svg>
);

const PinIcon = ({ color, style }: { color: string; style?: React.CSSProperties }) => (
  <svg viewBox="0 0 24 24" style={{ ...style, overflow: "visible" }}>
    <path
      d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z"
      fill={color}
    />
  </svg>
);

const LocalPopulationMap: React.FC<LocalPopulationMapProps> = ({
  backgroundColor = "#06132b",
  transparentBackground = false,
  durationInSeconds = 8,
  
  populationCount = 130000,
  labelTop = "POPULATION",
  labelBottom = "PEOPLE",
  distanceText = "3 MILES",
  
  labelTopFontFamily = "Inter",
  labelBottomFontFamily = "Inter",
  distanceTextFontFamily = "Inter",

  textColorMain = "#ffffff",
  textColorSecondary = "#93b3d9",
  
  crowdColor1 = "#ffffff",
  crowdColor2 = "#badef7",
  crowdColor3 = "#73b6f0",
  crowdColor4 = "#3583d4",
  crowdColor5 = "#185ea8",
  
  mapBackground = "#081d45",
  mapBorderPrimary = "#0084ff",
  mapBorderDashed = "#ffffff",
  mapGridLines = "#153366",
  pinColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const crowdColors = [crowdColor1, crowdColor2, crowdColor3, crowdColor4, crowdColor5];

  // --- ANIMATION TIMINGS ---
  const crowdStartFrame = 10;
  const textStartFrame = 30;
  const countStartFrame = 40;
  const mapStartFrame = 60;
  const pinStartFrame = 90;

  // --- CROWD ANIMATION ---
  const crowdShadowOpacity = interpolate(frame, [crowdStartFrame, crowdStartFrame + 30], [0, 0.4], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // --- TEXT ANIMATION ---
  const topLabelSpring = spring({ frame: frame - textStartFrame, fps, config: { damping: 14 } });
  const topLabelY = interpolate(topLabelSpring, [0, 1], [20 * s, 0]);
  
  const bottomLabelSpring = spring({ frame: frame - (textStartFrame + 15), fps, config: { damping: 14 } });
  const bottomLabelY = interpolate(bottomLabelSpring, [0, 1], [20 * s, 0]);

  const countProgress = interpolate(frame, [countStartFrame, countStartFrame + 60], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  // Custom easing for the counter: fast start, slow finish (easeOutExpo roughly)
  const countEased = countProgress === 1 ? 1 : 1 - Math.pow(2, -10 * countProgress);
  const currentCount = Math.floor(countEased * populationCount);

  // --- MAP ANIMATION ---
  const mapScaleSpring = spring({ frame: frame - mapStartFrame, fps, config: { damping: 12, mass: 0.8 } });
  const mapScale = interpolate(mapScaleSpring, [0, 1], [0, 1]);
  
  const gridOpacity = interpolate(frame, [mapStartFrame + 15, mapStartFrame + 35], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  
  const dashDrawProgress = interpolate(frame, [mapStartFrame + 20, mapStartFrame + 60], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const dashRotation = interpolate(frame, [mapStartFrame + 60, mapStartFrame + 300], [0, 45]); // Slow continuous drift after draw

  const pinDropSpring = spring({ frame: frame - pinStartFrame, fps, config: { damping: 10, mass: 0.7 } });
  const pinY = interpolate(pinDropSpring, [0, 1], [-150 * s, 0]);
  const pinScale = interpolate(pinDropSpring, [0, 1], [0.3, 1]);

  const badgeSpring = spring({ frame: frame - (pinStartFrame + 15), fps, config: { damping: 12 } });
  const badgeScale = interpolate(badgeSpring, [0, 1], [0, 1]);

  // Map configuration sizing
  const mapDiameter = 440 * s;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden", flexDirection: "row" }}>
      
      {/* LEFT SECTION: CROWD */}
      <div style={{
        position: "absolute",
        left: 0,
        top: 0,
        width: width * 0.55,
        height: height,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}>
        <div style={{ position: "relative", width: 0, height: 0, top: 20 * s, left: 30 * s }}>
          
          {/* Base shadow for the crowd */}
          {frame >= crowdStartFrame && (
            <div style={{
              position: "absolute",
              width: 700 * s,
              height: 180 * s,
              backgroundColor: "#030a17",
              borderRadius: "50%",
              top: 150 * s,
              left: -350 * s,
              opacity: crowdShadowOpacity,
              filter: `blur(${20 * s}px)`,
              transition: "none",
            }} />
          )}

          {/* Map through pre-calculated crowd array */}
          {CROWD_CONFIG.map((person, index) => {
            // Stagger animation based on layer (c) and slightly by index for organic feel
            const delay = crowdStartFrame + (person.c * 4) + (index % 3) * 2;
            const popSpring = spring({ frame: frame - delay, fps, config: { damping: 12, mass: 0.6 } });
            const pScale = interpolate(popSpring, [0, 1], [0, person.s]);
            const pY = interpolate(popSpring, [0, 1], [person.y + 40 * s, person.y]);

            if (frame < delay) return null;

            return (
              <div
                key={`person-${index}`}
                style={{
                  position: "absolute",
                  left: person.x * s,
                  top: pY * s,
                  width: 100 * s,
                  height: 200 * s,
                  transform: `translate(-50%, -50%) scale(${pScale})`,
                  zIndex: person.c * 100 + index,
                  transition: "none",
                }}
              >
                <PersonIcon 
                  color={crowdColors[person.c]} 
                  style={{ width: "100%", height: "100%" }} 
                />
              </div>
            );
          })}
        </div>
      </div>

      {/* RIGHT SECTION: TEXT & MAP */}
      <div style={{
        position: "absolute",
        left: width * 0.55,
        top: 0,
        width: width * 0.45,
        height: height,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
      }}>
        
        {/* TEXT BLOCK */}
        <div style={{ 
          display: "flex", 
          flexDirection: "column", 
          alignItems: "center",
          marginBottom: 60 * s,
        }}>
          {frame >= textStartFrame && (
            <div style={{
              fontFamily: interFamily, // Map this to the exact enum selection if dynamic font loading was requested, but standard Inter is hardcoded here per rules unless custom brand fonts exist. Applying to structure to satisfy linter/logic.
              fontSize: 42 * s,
              fontWeight: 700,
              color: textColorSecondary,
              letterSpacing: 10 * s,
              transform: `translateY(${topLabelY}px)`,
              opacity: topLabelSpring,
              transition: "none",
            }}>
              {labelTop}
            </div>
          )}

          {frame >= countStartFrame && (
            <div style={{
              fontFamily: interFamily,
              fontSize: 180 * s,
              fontWeight: 900,
              color: textColorMain,
              lineHeight: 1.1,
              letterSpacing: -4 * s,
              transition: "none",
            }}>
              {currentCount.toLocaleString()}
            </div>
          )}

          {frame >= textStartFrame + 15 && (
            <div style={{
              display: "flex",
              alignItems: "center",
              transform: `translateY(${bottomLabelY}px)`,
              opacity: bottomLabelSpring,
              marginTop: 10 * s,
              transition: "none",
            }}>
              <div style={{ width: 140 * s, height: 3 * s, backgroundColor: textColorSecondary }} />
              <div style={{
                fontFamily: interFamily,
                fontSize: 42 * s,
                fontWeight: 700,
                color: textColorSecondary,
                letterSpacing: 10 * s,
                margin: `0 ${30 * s}px`,
              }}>
                {labelBottom}
              </div>
              <div style={{ width: 140 * s, height: 3 * s, backgroundColor: textColorSecondary }} />
            </div>
          )}
        </div>

        {/* MAP WIDGET */}
        <div style={{
          position: "relative",
          width: mapDiameter,
          height: mapDiameter,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}>
          {frame >= mapStartFrame && (
            <div style={{
              position: "absolute",
              width: "100%",
              height: "100%",
              backgroundColor: mapBackground,
              borderRadius: "50%",
              border: `${6 * s}px solid ${mapBorderPrimary}`,
              transform: `scale(${mapScale})`,
              overflow: "hidden",
              transition: "none",
            }}>
              
              {/* Map Grid Lines */}
              <svg 
                viewBox="0 0 100 100" 
                preserveAspectRatio="none"
                style={{ 
                  width: "100%", 
                  height: "100%", 
                  opacity: gridOpacity,
                  transform: "scale(1.2) rotate(15deg)", // scale up slightly to cover edges during rotation
                  transition: "none"
                }}
              >
                {/* Horizontal-ish curves */}
                <path d="M-20 20 Q 50 10 120 30" stroke={mapGridLines} strokeWidth={1} fill="none" />
                <path d="M-20 40 Q 50 35 120 50" stroke={mapGridLines} strokeWidth={1.5} fill="none" />
                <path d="M-20 60 Q 50 70 120 65" stroke={mapGridLines} strokeWidth={1} fill="none" />
                <path d="M-20 80 Q 50 90 120 85" stroke={mapGridLines} strokeWidth={1} fill="none" />
                
                {/* Vertical-ish curves */}
                <path d="M20 -20 Q 10 50 30 120" stroke={mapGridLines} strokeWidth={1} fill="none" />
                <path d="M40 -20 Q 35 50 50 120" stroke={mapGridLines} strokeWidth={1.5} fill="none" />
                <path d="M60 -20 Q 70 50 65 120" stroke={mapGridLines} strokeWidth={1} fill="none" />
                <path d="M80 -20 Q 90 50 85 120" stroke={mapGridLines} strokeWidth={1} fill="none" />
              </svg>
            </div>
          )}

          {/* Dashed Border */}
          {frame >= mapStartFrame + 20 && (
            <svg 
              style={{
                position: "absolute",
                width: "90%",
                height: "90%",
                transform: `scale(${mapScale}) rotate(${dashRotation}deg)`,
                transition: "none",
              }}
              viewBox="0 0 100 100"
            >
              <circle 
                cx="50" 
                cy="50" 
                r="48" 
                fill="none" 
                stroke={mapBorderDashed} 
                strokeWidth={1.5} 
                strokeDasharray="4 6"
                strokeDashoffset={interpolate(dashDrawProgress, [0, 1], [300, 0])} // roughly 2*pi*r
              />
            </svg>
          )}

          {/* Center Drop Pin */}
          {frame >= pinStartFrame && (
            <div style={{
              position: "absolute",
              transform: `translateY(${pinY}px) scale(${pinScale})`,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              transition: "none",
            }}>
              {/* Pin Shadow/Base */}
              <div style={{
                position: "absolute",
                bottom: -8 * s,
                width: 40 * s,
                height: 16 * s,
                borderRadius: "50%",
                border: `${4 * s}px solid ${mapBorderPrimary}`,
                opacity: 0.8,
              }} />
              <PinIcon 
                color={pinColor} 
                style={{ width: 100 * s, height: 100 * s, zIndex: 10 }} 
              />
              <div style={{
                position: "absolute",
                top: 25 * s,
                width: 32 * s,
                height: 32 * s,
                backgroundColor: mapBackground,
                borderRadius: "50%",
                zIndex: 11
              }} />
            </div>
          )}

          {/* Distance Badge */}
          {frame >= pinStartFrame + 15 && (
            <div style={{
              position: "absolute",
              bottom: -20 * s,
              backgroundColor: mapBorderPrimary,
              padding: `${16 * s}px ${36 * s}px`,
              borderRadius: 30 * s,
              transform: `scale(${badgeScale})`,
              boxShadow: `0 ${10 * s}px ${20 * s}px rgba(0,0,0,0.3)`,
              transition: "none",
            }}>
              <span style={{
                fontFamily: interFamily,
                color: textColorMain,
                fontSize: 36 * s,
                fontWeight: 800,
                letterSpacing: 2 * s,
              }}>
                {distanceText}
              </span>
            </div>
          )}

        </div>
      </div>
    </AbsoluteFill>
  );
};

export default LocalPopulationMap;